function ChatRoom({ roomId }) {
  const [serverUrl, setServerUrl] =
    useState("https://localhost:1234");
  useChatRoom({ roomId, serverUrl });
}

function useChatRoom({ serverUrl, roomId }) {
  useEffect(() => {
    const c = createConnection({ serverUrl, roomId });
    c.connect();
    return () => c.disconnect();
  }, [roomId, serverUrl]);
}
